def normalize_equipment_class(class_key: object) -> str:
    key = str(class_key or "").strip().lower()
    if key not in SUPPORTED_CLASSES:
        raise ValueError(f"Unsupported equipment target class: {class_key!r}")
    return key

def _validate_weight_profile(profile: object, label: str) -> tuple[tuple[str, int], ...]:
    if not isinstance(profile, tuple) or not profile:
        raise ValueError(f"{label}: profile must be a non-empty tuple")
    seen = set()
    total = 0
    normalized = []
    for entry in profile:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError(f"{label}: invalid weighted entry {entry!r}")
        stat_key, weight = entry
        if stat_key not in PRIMARY_STATS or stat_key in seen:
            raise ValueError(f"{label}: invalid or duplicate stat {stat_key!r}")
        if isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0:
            raise ValueError(f"{label}: invalid weight for {stat_key}: {weight!r}")
        seen.add(stat_key)
        total += weight
        normalized.append((stat_key, weight))
    if total != 100:
        raise ValueError(f"{label}: weights total {total}, expected 100")
    return tuple(normalized)

def get_equipment_stat_weights(
    class_key: object,
    equipment_kind: str,
    *,
    item_subtype: str = "",
) -> tuple[tuple[str, int], ...]:
    """Return immutable weighted primary-stat choices for one target class."""
    cls = normalize_equipment_class(class_key)
    kind = str(equipment_kind or "").strip().lower()
    subtype = str(item_subtype or "").strip().lower()
    if kind not in SUPPORTED_EQUIPMENT_KINDS:
        raise ValueError(f"Unsupported equipment kind: {equipment_kind!r}")
    if kind == "weapon":
        if subtype and subtype not in CLASS_MAIN_HAND_SUBTYPES[cls]:
            raise ValueError(f"Main-hand subtype {subtype!r} is not allowed for {cls}")
        profile = MAIN_HAND_STAT_WEIGHTS[cls]
    elif kind == "armor":
        profile = ARMOR_STAT_WEIGHTS[cls]
    elif kind == "jewelry":
        profile = JEWELRY_STAT_WEIGHTS[cls]
    else:
        if subtype not in CLASS_OFF_HAND_SUBTYPES[cls]:
            raise ValueError(f"Off-hand subtype {subtype!r} is not allowed for {cls}")
        profile = OFF_HAND_STAT_WEIGHTS[(cls, subtype)]
    return _validate_weight_profile(profile, f"{cls}:{kind}:{subtype or '*'}")

def validate_equipment_stat_policy() -> tuple[str, ...]:
    problems = []
    expected_classes = set(SUPPORTED_CLASSES)
    for label, mapping in (
        ("CLASS_STAT_WEIGHTS", CLASS_STAT_WEIGHTS),
        ("MAIN_HAND_STAT_WEIGHTS", MAIN_HAND_STAT_WEIGHTS),
        ("JEWELRY_STAT_WEIGHTS", JEWELRY_STAT_WEIGHTS),
        ("CLASS_ARMOR_TYPES", CLASS_ARMOR_TYPES),
        ("CLASS_MAIN_HAND_SUBTYPES", CLASS_MAIN_HAND_SUBTYPES),
        ("CLASS_OFF_HAND_SUBTYPES", CLASS_OFF_HAND_SUBTYPES),
    ):
        if set(mapping) != expected_classes:
            problems.append(f"{label}: class set mismatch")
    for cls in SUPPORTED_CLASSES:
        for kind in ("weapon", "armor", "jewelry"):
            try:
                profile = get_equipment_stat_weights(cls, kind)
                _validate_weight_profile(profile, f"{cls}:{kind}")
            except Exception as error:
                problems.append(str(error))
        for subtype in CLASS_OFF_HAND_SUBTYPES[cls]:
            try:
                get_equipment_stat_weights(cls, "off_hand", item_subtype=subtype)
            except Exception as error:
                problems.append(str(error))
    if get_allowed_equipment_stats("knight", "off_hand", item_subtype="shield") != ("sta", "str"):
        problems.append("Knight shield must allow exactly STA and STR")
    return tuple(problems)

def redistribute_primary_stat_budget(stats, class_key, equipment_kind, *, item_subtype="", chooser):
    """Redistribute existing positive primary-stat chunks by canonical class policy.

    The total primary-stat budget and number of generated chunks are preserved.
    `chooser` receives the immutable weighted profile and returns one stat key.
    """
    if not callable(chooser):
        raise ValueError("chooser must be callable")
    profile = get_equipment_stat_weights(class_key, equipment_kind, item_subtype=item_subtype)
    allowed = {stat for stat, _weight in profile}
    result = dict(stats)
    chunks = []
    for stat_key in PRIMARY_STATS:
        column = "bonus_" + stat_key
        value = int(result.get(column, 0) or 0)
        if value > 0:
            chunks.append(value)
        result[column] = 0
    if not chunks:
        return result
    for value in chunks:
        selected = str(chooser(profile) or "").strip().lower()
        if selected not in allowed:
            raise ValueError(f"chooser returned forbidden stat {selected!r}")
        column = "bonus_" + selected
        result[column] = int(result.get(column, 0) or 0) + value
    if sum(int(result.get("bonus_" + stat, 0) or 0) for stat in PRIMARY_STATS) != sum(chunks):
        raise ValueError("primary-stat budget changed during redistribution")
    return result

def validate_location_graph():
    errors=[]
    for node, neighbors in LOCATION_GRAPH.items():
        if node not in WORLD_NODES: errors.append(f"unknown graph node: {node}")
        if len(neighbors) != len(set(neighbors)): errors.append(f"duplicate edge from: {node}")
        for neighbor in neighbors:
            if neighbor not in WORLD_NODES: errors.append(f"unknown neighbor: {neighbor}")
            elif node not in LOCATION_GRAPH.get(neighbor, ()): errors.append(f"asymmetric edge: {node}->{neighbor}")
    if set(WORLD_NODES) != set(LOCATION_GRAPH): errors.append("WORLD_NODES and LOCATION_GRAPH keys differ")
    if errors: raise ValueError("; ".join(errors))
    return True

def is_location_unlocked(location_id, player_level):
    location = LOCATIONS.get(location_id)

    if not location:
        return False

    return player_level >= location["unlock_level"]

def get_exp_to_next_level(level: int) -> int:
    level = int(level)
    base_exp = get_base_exp_for_level(level)
    if level in CONDITIONAL_MOBS_TO_NEXT_BY_LEVEL:
        return int(base_exp * CONDITIONAL_MOBS_TO_NEXT_BY_LEVEL[level])
    mobs_required = int(CONDITIONAL_MOBS_TO_NEXT_BY_LEVEL[MAX_CONFIGURED_LEVEL] * (1.10 ** (level - MAX_CONFIGURED_LEVEL)))
    return int(base_exp * mobs_required)

def _number(value: object, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be an int or float, excluding bool")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError(f"{name} must be finite")
    if result < 0.0:
        raise ValueError(f"{name} must be non-negative")
    return result

def validate_class_scaling(candidate: Mapping[str, Mapping[str, Mapping[str, object]]]) -> None:
    if set(candidate) != set(SUPPORTED_CLASSES):
        raise ValueError("candidate must define exactly the six supported classes")
    for class_key in SUPPORTED_CLASSES:
        entry = candidate[class_key]
        if set(entry) != {"patk", "matk"}:
            raise ValueError(f"{class_key} must define patk and matk")
        for attack_kind in ("patk", "matk"):
            coefficients = entry[attack_kind]
            if not coefficients:
                raise ValueError(f"{class_key}.{attack_kind} must not be empty")
            for stat_name, coefficient in coefficients.items():
                if stat_name not in SUPPORTED_STATS:
                    raise ValueError(f"unsupported stat: {stat_name}")
                _number(coefficient, f"{class_key}.{attack_kind}.{stat_name}")

def validate_story_hierarchy_metadata() -> dict[str, object]:
    """Validate registry coverage, ordering, localization, and section contracts."""
    production_by_number = {quest.number: quest for quest in STORY_QUEST_REGISTRY.values()}
    production_numbers = tuple(production_by_number)
    metadata_numbers: list[int] = []
    seen_numbers: set[int] = set()

    if tuple(sorted(STORY_LOCATIONS, key=lambda location_id: STORY_LOCATIONS[location_id].sort_order)) != tuple(
        story.story_id for story in ordered_story_locations()
    ):
        raise ValueError("Story location ordering is not stable")

    for story in ordered_story_locations():
        if story.story_id != story.location_id:
            raise ValueError(f"Story ID must equal canonical location ID: {story.story_id}")
        if story.display_name != "Початок Шляху" and story.location_id == "start_path":
            raise ValueError("start_path must resolve to Початок Шляху")
        if story.location_id in story.button_label or "Start Path" in story.button_label:
            raise ValueError("Technical location ID leaked into player-facing story label")
        sections = ordered_story_sections(story.location_id)
        if tuple(section.section_id for section in sections) != story.section_ids:
            raise ValueError(f"Section order mismatch for {story.story_id}")
        expected_section_numbers = tuple(range(1, len(sections) + 1))
        if tuple(section.number for section in sections) != expected_section_numbers:
            raise ValueError(f"Section numbers must be continuous for {story.story_id}")

        for section in sections:
            if section.location_id != story.location_id:
                raise ValueError(f"Section {section.section_id} location mismatch")
            if "глава" in section.display_title.casefold():
                raise ValueError(f"Forbidden Ukrainian term in {section.section_id}")
            if not section.display_title.startswith("Розділ "):
                raise ValueError(f"Invalid section presentation title: {section.display_title}")
            if not section.quest_numbers:
                raise ValueError(f"Empty section: {section.section_id}")
            if section.quest_numbers != tuple(range(section.quest_numbers[0], section.quest_numbers[-1] + 1)):
                raise ValueError(f"Non-contiguous quest range: {section.section_id}")
            for quest_number in section.quest_numbers:
                if quest_number in seen_numbers:
                    raise ValueError(f"Quest {quest_number} belongs to multiple sections")
                seen_numbers.add(quest_number)
                metadata_numbers.append(quest_number)
                quest = production_by_number.get(quest_number)
                if quest is None:
                    raise ValueError(f"Metadata exposes inactive quest {quest_number}")
                if quest.location_id != story.location_id:
                    raise ValueError(f"Quest {quest_number} location mismatch")
                if quest.unlock_level != section.required_level:
                    raise ValueError(f"Quest {quest_number} unlock level mismatch")

    if tuple(metadata_numbers) != production_numbers:
        raise ValueError(
            f"Hierarchy coverage mismatch: metadata={tuple(metadata_numbers)}, production={production_numbers}"
        )

    return {
        "story_ids": tuple(story.story_id for story in ordered_story_locations()),
        "section_ids": tuple(section.section_id for section in STORY_SECTIONS.values()),
        "quest_numbers": tuple(metadata_numbers),
        "production_quest_count": len(production_numbers),
        "metadata_quest_count": len(metadata_numbers),
        "localized_start_path": STORY_LOCATIONS["start_path"].display_name,
        "start_path_button_label": STORY_LOCATIONS["start_path"].button_label,
        "section_titles": tuple(section.display_title for section in ordered_story_sections("start_path")),
    }

def validate_story_quest_item_key(item_key: str) -> str:
    """Return a stable canonical key or reject an inventory-like identity."""
    key = str(item_key or "").strip()
    if not STORY_QUEST_ITEM_KEY_PATTERN.fullmatch(key):
        raise ValueError(
            "story quest item_key must be lowercase snake_case with a namespace prefix"
        )
    return key

def validate_story_quest_item_schema(connection) -> dict:
    """Fail closed if virtual quest items can overlap ordinary inventory identity."""
    result = inspect_story_quest_item_schema(connection)
    errors = []
    if result["missing_required"]:
        errors.append(f"missing columns: {result['missing_required']}")
    if result["forbidden_present"]:
        errors.append(f"forbidden columns: {result['forbidden_present']}")
    if not result["identity_unique"]:
        errors.append("missing UNIQUE(user_id, quest_id, item_key)")
    if "user_story_quests" not in result["foreign_key_tables"]:
        errors.append("missing foreign key to user_story_quests")
    if errors:
        raise RuntimeError("; ".join(errors))
    result["status"] = "PASS"
    return result

