def _auction_get_admin_ids_v1():
    import os

    raw = (
        os.getenv("AUCTION_ADMIN_IDS")
        or os.getenv("ADMIN_USER_IDS")
        or "243129101"
    )

    result = set()

    for part in str(raw).replace(";", ",").split(","):
        part = part.strip()
        if not part:
            continue
        try:
            result.add(int(part))
        except Exception:
            pass

    return result

