    result = _blacksmith_base_build_blacksmith_repair_text_before_confirm_v3(user_id)

    if isinstance(result, tuple):
        if len(result) >= 2:
            text, kb = result[0], result[1]
            return text, _blacksmith_rewrite_repair_callbacks_v3(kb)
