        bonuses.append(f"🛡 Витривалість +{b_sta}")



    if pdef:



        bonuses.append(f"🛡 Фіз. захист +{pdef}")



    if mdef:



        bonuses.append(f"🔮 Маг. захист +{mdef}")







    return bonuses

