def confirm(call):
        parts = str(call.data).split(":")
        try:
            trade_id, revision = int(parts[3]), int(parts[4])
        except (IndexError, TypeError, ValueError):
            return
        result = confirm_player_trade(
            trade_id,
            int(call.from_user.id),
            expected_revision=revision,
        )
        if not result.get("success"):
            _safe_answer(
                bot, call,
                result.get("message") or "Не вдалося завершити обмін.",
                True,
            )
            return
        _safe_answer(bot, call)
        if not result.get("completed"):
            state = get_player_trade_editor_state(trade_id, int(call.from_user.id))
            if not state.get("success"):
                return
            _trade_show_current_stage_12_7_0(
                bot, call.message.chat.id, int(call.from_user.id), trade_id,
                call.message.message_id,
            )
            if result.get("changed"):
                _trade_send_synchronized_stage_12_7_0(bot, state)
            return

        text = (
            "✅ <b>Обмін успішно завершено</b>\n\n"
            "Предмети та золото передано!"
        )
        try:
            from keyboards import main_kb
            for user_id in (
                int(result.get("initiator_user_id") or call.from_user.id),
                int(result.get("recipient_user_id") or call.from_user.id),
            ):
                bot.send_message(
                    user_id, text, parse_mode="HTML", reply_markup=get_location_context_kb(user_id),
                )
        except Exception:
            pass

def _build_text(data,viewer_user_id):
 category=data['category'];lines=[f"🏆 Рейтинг: {category['label']}",'']
 for row in data['items']:
  own=' 👤' if int(row['user_id'])==int(viewer_user_id) else ''
  lines.extend([f"{row['position']}. {row['character_name']}{own}",f"   Рівень: {int(row['level'])} | {category['value_label']}: {_format_value(data['ranking_key'],row['value'])}"])
 if not data['items']:lines.append('У рейтингу ще немає персонажів.')
 viewer=data.get('viewer')
 if viewer and not data.get('viewer_on_page'):
  lines.extend(['',f"Твоє місце: {viewer['position']}",f"Твоє значення: {_format_value(data['ranking_key'],viewer['value'])}"])
 return '\n'.join(lines)

def format_equipment_bonuses(b_str, b_dex, b_int, b_wis, b_sta, pdef, mdef):

    bonuses = []



    if b_str:

        bonuses.append(f"💪 Сила +{b_str}")

    if b_dex:

        bonuses.append(f"🎯 Спритність +{b_dex}")

    if b_int:

        bonuses.append(f"🔮 Інтелект +{b_int}")

    if b_wis:

        bonuses.append(f"🦉 Мудрість +{b_wis}")

    if b_sta:

