        bot.answer_callback_query(call.id,"Дуель завершено.")
        for row in get_pvp_participants(battle_id):
            uid=int(row["user_id"])
            try: bot.send_message(uid,render_pvp_terminal_text(battle_id,uid),parse_mode="HTML",reply_markup=_main_kb())
            except Exception: log.exception("Cannot send PvP surrender result")

def get_refinable_inventory_items(user_id):
    result = []
    items = get_inventory_detailed(user_id)

    for item in items:
        try:
            inventory_id = item[0]
        except Exception:
            continue

        info = get_inventory_item_refine_info(inventory_id)
        check = can_refine_item(info)

        if not check.get("refine_kind"):
            continue

        current_level = int(info.get("refine_level", 0) or 0)
        max_level = int(check.get("max_level", 0) or 0)

        if max_level <= 0:
            continue

        name = get_inventory_refined_display_name(
            inventory_id,
            info.get("name", "Предмет")
        )

        result.append({
            "inventory_id": inventory_id,
            "name": name,
            "refine_kind": check.get("refine_kind", ""),
            "current_level": current_level,
            "max_level": max_level,
            "can_refine": bool(check.get("success")),
        })

    return result

