                call.message.chat.id,
                f"🔮 Клас змінено.\n\nБуло: {old_class}\nСтало: {new_class}{unequip_text}",
            )
        bot.send_message(
            call.message.chat.id,
            build_main_menu_text(call.from_user.id),
            reply_markup=main_kb(),
        )

