def _callback(*parts: object) -> str:
    value = ":".join((CALLBACK_PREFIX, *(str(part) for part in parts)))
    if len(value.encode("utf-8")) > 64:
        raise ValueError(f"Story hierarchy callback is too long: {value}")
    return value

def _completed_numbers(user_id: int, status_reader: Callable[[int, object], str]) -> set[int]:
    completed = set()
    for quest in STORY_QUEST_REGISTRY.values():
        if status_reader(user_id, quest) == "completed":
            completed.add(quest.number)
    return completed

def _section_status(user_id: int, section, status_reader: Callable[[int, object], str]) -> str:
    rows = _registry_by_number()
    statuses = [status_reader(user_id, rows[number]) for number in section.quest_numbers if number in rows]
    if statuses and all(status == "completed" for status in statuses):
        return "completed"
    if "active" in statuses:
        return "active"
    if "available" in statuses:
        return "available"
    # A fully finalized section containing SKIPPED quests is not locked. Keep
    # progress honest by counting only COMPLETED, while ⏭️ explains closure.
    if "skipped" in statuses and all(status in {"completed", "skipped"} for status in statuses):
        return "skipped"
    return "locked"

def _quest_by_number(number):
 matches=[quest for quest in STORY_QUEST_REGISTRY.values() if quest.number==int(number)]
 if len(matches)!=1:raise ValueError('Невідомий або неоднозначний номер квесту.')
 return matches[0]

def _callback_data(action,npc_id,quest):
 token=CALLBACK_ACTIONS[action]
 data=f'{CALLBACK_PREFIX}{token}:{npc_id}:{quest.number}'
 if len(data.encode('utf-8'))>64:raise ValueError('Story callback перевищує ліміт Telegram.')
 return data

