def _auction_get_durability(row_dict):
    current = None
    maximum = None

    current_keys = [
        "durability",
        "current_durability",
        "durability_current",
        "inventory_durability",
        "item_durability",
    ]
    max_keys = [
        "max_durability",
        "durability_max",
        "inventory_max_durability",
        "item_max_durability",
    ]

    for key in current_keys:
        if key in row_dict and row_dict.get(key) is not None:
            try:
                current = int(row_dict.get(key))
                break
            except Exception:
                pass

    for key in max_keys:
