        raise

    _equipment_sync_hp_9_0_12h2(user_id)

    return {

        "success": True,

        "message": (

            "✅ Усе спорядження відремонтовано.\n\n"

            f"📦 Відремонтовано предметів: {len(items)}\n"

            f"💳 Сплачено: {total:.2f} 💰 золото"

