def buy_item_for_gold(user_id, item_id, price, quantity=1):

    """Atomic generic purchase with wallet, stacking and bag-capacity checks."""

    db = _trader_db_9_0_12h3()

    uid = int(user_id)

    item_id = int(item_id)

    quantity = max(1, int(quantity or 1))

    price = round(max(0.0, float(price or 0.0)), 2)

    try:

        db.conn.execute("BEGIN IMMEDIATE")

        item = db.conn.execute(

            "SELECT name, COALESCE(max_stack,1) FROM items WHERE id=?",

            (item_id,),

        ).fetchone()

        if not item:

            db.conn.rollback()

            return {"success": False, "message": "❌ Товар не знайдено."}

        name, max_stack = item

        wallet = _trader_wallet_9_0_12h3(db, uid)

        if wallet + 1e-9 < price:

            db.conn.rollback()

            return {"success": False, "message": f"❌ Недостатньо золота. Потрібно: {price:.2f} 💰"}



        max_stack = max(1, int(max_stack or 1))

        stack = None

        if max_stack > 1:

            stack = db.conn.execute(

                "SELECT id, quantity FROM inventory WHERE user_id=? AND item_id=? "

                "AND quantity<? ORDER BY id ASC LIMIT 1",

                (uid, item_id, max_stack),

            ).fetchone()

        if stack and int(stack[1] or 0) + quantity <= max_stack:

            db.conn.execute(

                "UPDATE inventory SET quantity=quantity+? WHERE id=? AND user_id=?",

                (quantity, int(stack[0]), uid),

            )

            inventory_id = int(stack[0])

        else:

            used, capacity = _trader_bag_state_9_0_12h3(db, uid)

            if used >= capacity:

                db.conn.rollback()

                return {"success": False, "message": "❌ У сумці немає вільного місця."}

            cur = db.conn.execute(

                "INSERT INTO inventory (user_id,item_id,quantity,durability,refine_level) "

                "VALUES (?,?,?,100,0)",

                (uid, item_id, quantity),

            )

            inventory_id = int(cur.lastrowid)

        db.conn.execute("UPDATE users SET gold=gold-? WHERE user_id=?", (price, uid))

        db.conn.commit()

    except Exception:

        db.conn.rollback()

        raise

    return {

        "success": True,

        "message": f"✅ Куплено: {name} ×{quantity}\n💳 Сплачено: {price:.2f} 💰 золота",

        "inventory_id": inventory_id,

        "item_id": item_id,

        "quantity": quantity,

        "price": price,

        "name": str(name),

    }

def buy_common_equipment_from_trader(user_id, slot_key, item_profile=None):

    """

    Preserve the direct-buy API while using the established preview workflow.

    Preview ownership, class restrictions, price and item generation remain validated

    by the existing preview functions; confirmation is still a single purchase action.

    """

    db = _trader_db_9_0_12h3()

    uid = int(user_id)

    slot_key = str(slot_key or "")

    if slot_key not in _TRADER_EQUIPMENT_SLOTS_9_0_12H3:

        return {"success": False, "message": "❌ Невідомий слот спорядження."}



    allowed = getattr(db, "is_shop_profile_allowed_for_user", None)

    if item_profile and callable(allowed):

        try:

            if not allowed(uid, slot_key, item_profile):

                return {"success": False, "message": "❌ Цей тип спорядження не підходить твоєму класу."}

        except Exception:

            pass



    create_preview = getattr(db, "create_common_equipment_shop_preview", None)

    confirm_preview = getattr(db, "confirm_common_equipment_shop_preview", None)

    if not callable(create_preview) or not callable(confirm_preview):

        return {"success": False, "message": "❌ Магазин спорядження тимчасово недоступний."}



    preview = create_preview(uid, slot_key, item_profile)

    if isinstance(preview, dict) and not preview.get("success", True):

        return preview

    if isinstance(preview, dict):

        preview_id = preview.get("item_id") or preview.get("preview_item_id") or preview.get("id")

    else:

        preview_id = preview

    if not preview_id:

        return {"success": False, "message": "❌ Не вдалося створити товар магазину."}

    return confirm_preview(uid, int(preview_id))

def validate_event_item_catalog_definitions(definitions=None):
    items = get_registered_event_item_definitions() if definitions is None else tuple(definitions)
    seen = set()
    for item in items:
        item_id = int(item["id"])
        if item_id in seen:
            raise ValueError("duplicate event item ID")
        seen.add(item_id)
        if not str(item.get("name") or "").strip():
            raise ValueError("event item name is required")
        if int(item.get("max_stack") or 0) <= 0:
            raise ValueError("event item max_stack must be positive")
        for flag in ("tradeable", "sellable", "auctionable"):
            if item.get(flag) is not False:
                raise ValueError(f"pilot item must explicitly set {flag}=False")
        if float(item.get("sell_price", 0.0)) != 0.0:
            raise ValueError("pilot item sell_price must be zero")
    return items

def seed_event_item_catalog(connection=None, *, commit=True):
    if connection is None:
        from db_modules.connection import conn as connection
    definitions = validate_event_item_catalog_definitions()
    sql = """
        INSERT INTO items (
            id,name,type,rarity,category,slot_key,weapon_hands,max_stack,sell_price,
            bonus_str,bonus_dex,bonus_int,bonus_wis,bonus_sta,pdef,mdef
        ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(id) DO UPDATE SET
            name=excluded.name,type=excluded.type,rarity=excluded.rarity,
            category=excluded.category,slot_key=excluded.slot_key,
            weapon_hands=excluded.weapon_hands,max_stack=excluded.max_stack,
            sell_price=excluded.sell_price,bonus_str=excluded.bonus_str,
            bonus_dex=excluded.bonus_dex,bonus_int=excluded.bonus_int,
            bonus_wis=excluded.bonus_wis,bonus_sta=excluded.bonus_sta,
            pdef=excluded.pdef,mdef=excluded.mdef
    """
    rows = tuple(_catalog_row(item) for item in definitions)
    try:
        for row in rows:
            connection.execute(sql, row)
        if commit:
            connection.commit()
    except Exception:
        if commit:
            connection.rollback()
        raise
    return {"success": True, "seeded": len(rows), "item_ids": tuple(row[0] for row in rows)}

def _key(value,name):
 value=str(value or "").strip()
 if not value: raise ValueError(f"{name} must be non-empty")
 return value

def _offer(event_key,offer_key):
 import events
 events.load_event_modules()
 for module in events.get_registered_events():
  if module.config.EVENT_KEY!=event_key: continue
  provider=getattr(module,"get_shop_offers",None)
  for offer in (() if provider is None else provider()):
   if str(offer.get("offer_key"))==offer_key: return module,offer
 raise ValueError("event shop offer not found")

def _reserved(conn,user_id,item_id):
 if not conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='inventory_reservations'").fetchone(): return 0
 columns={r[1] for r in conn.execute("PRAGMA table_info(inventory_reservations)")}
 if not {"inventory_id","quantity"}.issubset(columns): return 0
 return int(conn.execute("""SELECT COALESCE(SUM(r.quantity),0) FROM inventory_reservations r
 JOIN inventory i ON i.id=r.inventory_id WHERE i.user_id=? AND i.item_id=? AND COALESCE(r.quantity,0)>0""",(user_id,item_id)).fetchone()[0] or 0)

def _consume(conn,user_id,item_id,quantity):
 remaining=quantity
 for row_id,current in conn.execute("SELECT id,quantity FROM inventory WHERE user_id=? AND item_id=? ORDER BY id",(user_id,item_id)).fetchall():
  take=min(remaining,int(current or 0)); new=int(current or 0)-take
  if new: conn.execute("UPDATE inventory SET quantity=? WHERE id=?",(new,row_id))
  else: conn.execute("DELETE FROM inventory WHERE id=?",(row_id,))
  remaining-=take
  if remaining==0: break
 if remaining: raise RuntimeError("insufficient quantity during debit")

def _award(conn,user_id,item_id,quantity):
 max_stack=int(conn.execute("SELECT COALESCE(max_stack,1) FROM items WHERE id=?",(item_id,)).fetchone()[0] or 1)
 partial=conn.execute("SELECT id,quantity FROM inventory WHERE user_id=? AND item_id=? AND quantity<? ORDER BY id",(user_id,item_id,max_stack)).fetchall()
 free=sum(max_stack-int(r[1] or 0) for r in partial); needed=max(0,quantity-free); new_stacks=(needed+max_stack-1)//max_stack
 capacity=int(conn.execute("SELECT COALESCE(bag_slots,60) FROM users WHERE user_id=?",(user_id,)).fetchone()[0] or 60); used=int(conn.execute("SELECT COUNT(*) FROM inventory WHERE user_id=?",(user_id,)).fetchone()[0])
 if used+new_stacks>capacity: raise ValueError("bag_full")
 remaining=quantity
 for row_id,current in partial:
  moved=min(remaining,max_stack-int(current or 0)); conn.execute("UPDATE inventory SET quantity=? WHERE id=?",(int(current or 0)+moved,row_id)); remaining-=moved
  if not remaining: break
 while remaining:
  amount=min(remaining,max_stack); conn.execute("INSERT INTO inventory(user_id,item_id,quantity,durability) VALUES(?,?,?,NULL)",(user_id,item_id,amount)); remaining-=amount

def exchange_event_shop_offer(conn,event_key,user_id,offer_key,idempotency_key,*,event_active=False,now=None):
 event_key=_key(event_key,"event_key"); offer_key=_key(offer_key,"offer_key"); idem=_key(idempotency_key,"idempotency_key"); user_id=int(user_id)
 module,offer=_offer(event_key,offer_key)
 if not event_active or not module.config.ENABLED: return {"success":False,"reason":"event_inactive"}
 if offer.get("operation_kind")!="exchange" or offer.get("reward_kind")!="static_item": raise ValueError("unsupported event shop operation")
 existing=conn.execute("SELECT id FROM event_shop_transactions WHERE idempotency_key=?",(idem,)).fetchone()
 if existing: return {"success":True,"duplicate":True,"transaction_id":int(existing[0])}
 cost_id=int(offer["cost_item_id"]); cost_q=int(offer["cost_quantity"]); reward_id=int(offer["reward_item_id"]); reward_q=int(offer["reward_quantity"])
 conn.execute("SAVEPOINT event_exchange")
 try:
  total=int(conn.execute("SELECT COALESCE(SUM(quantity),0) FROM inventory WHERE user_id=? AND item_id=?",(user_id,cost_id)).fetchone()[0] or 0)
  if total-_reserved(conn,user_id,cost_id)<cost_q: raise ValueError("insufficient_unreserved_currency")
  _award(conn,user_id,reward_id,reward_q); _consume(conn,user_id,cost_id,cost_q)
  cur=conn.execute("""INSERT INTO event_shop_transactions(idempotency_key,event_key,user_id,offer_key,operation_kind,reward_kind,cost_item_id,cost_quantity,reward_item_id,reward_quantity,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",(idem,event_key,user_id,offer_key,"exchange","static_item",cost_id,cost_q,reward_id,reward_q,(now or datetime.now(timezone.utc)).isoformat()))
  conn.execute("RELEASE event_exchange"); return {"success":True,"duplicate":False,"transaction_id":int(cur.lastrowid)}
 except Exception:
  conn.execute("ROLLBACK TO event_exchange"); conn.execute("RELEASE event_exchange"); raise

def _text(value,name):
    result=str(value or "").strip()
    if not result: raise ValueError(f"{name} must be non-empty")
    return result

def record_event_mob_victory(conn,event_key,user_id,mob_key,terminal_event_id,*,now=None):
    event_key=_text(event_key,"event_key"); mob_key=_text(mob_key,"mob_key"); terminal_event_id=_text(terminal_event_id,"terminal_event_id"); user_id=int(user_id)
    timestamp=(now or datetime.now(timezone.utc)).astimezone(timezone.utc).isoformat()
    conn.execute("SAVEPOINT event_kill_record")
    try:
        cur=conn.execute("INSERT OR IGNORE INTO event_kill_receipts(event_key,terminal_event_id,user_id,mob_key,recorded_at) VALUES(?,?,?,?,?)",(event_key,terminal_event_id,user_id,mob_key,timestamp))
        if cur.rowcount==0:
            conn.execute("RELEASE event_kill_record"); return {"success":True,"recorded":False,"duplicate":True}
        conn.execute("""INSERT INTO event_kill_statistics(event_key,user_id,mob_key,kills,first_reached_at,updated_at) VALUES(?,?,?,?,?,?)
          ON CONFLICT(event_key,user_id,mob_key) DO UPDATE SET kills=kills+1,updated_at=excluded.updated_at""",(event_key,user_id,mob_key,1,timestamp,timestamp))
        kills=conn.execute("SELECT kills FROM event_kill_statistics WHERE event_key=? AND user_id=? AND mob_key=?",(event_key,user_id,mob_key)).fetchone()[0]
        conn.execute("RELEASE event_kill_record"); return {"success":True,"recorded":True,"duplicate":False,"kills":int(kills)}
    except Exception:
        conn.execute("ROLLBACK TO event_kill_record"); conn.execute("RELEASE event_kill_record"); raise

def get_event_kill_leaderboard(conn,event_key,mob_key,*,page=1,page_size=10,top_size=100,user_id=None):
    event_key=_text(event_key,"event_key"); mob_key=_text(mob_key,"mob_key"); page=max(1,int(page)); page_size=int(page_size); top_size=int(top_size)
    if page_size!=10 or top_size!=100: raise ValueError("canonical leaderboard requires page_size=10 and top_size=100")
    rows=conn.execute("""SELECT user_id,kills,first_reached_at FROM event_kill_statistics WHERE event_key=? AND mob_key=?
      ORDER BY kills DESC,first_reached_at ASC,user_id ASC LIMIT ? OFFSET ?""",(event_key,mob_key,min(page_size,max(0,top_size-(page-1)*page_size)),(page-1)*page_size)).fetchall()
    own=None
    if user_id is not None:
        ranked=conn.execute("""SELECT user_id,kills,first_reached_at FROM event_kill_statistics WHERE event_key=? AND mob_key=? ORDER BY kills DESC,first_reached_at ASC,user_id ASC""",(event_key,mob_key)).fetchall()
        for index,row in enumerate(ranked,1):
            if int(row[0])==int(user_id): own={"rank":index,"user_id":int(row[0]),"kills":int(row[1])}; break
    return {"page":page,"page_size":10,"top_size":100,"entries":[{"rank":(page-1)*10+i,"user_id":int(r[0]),"kills":int(r[1])} for i,r in enumerate(rows,1)],"own":own}

def init_fatigue_artifact_system(db_path=None):
