def choose(a,catalog):
 skills=catalog[a.class_key]
 for s in reversed(skills):
  if a.cooldowns.get(s["key"],0)>1: continue
  t=s.get("cost_type"); cost=int(s.get("cost") or 0)
  if t=="mana" and a.mp<cost: continue
  if t=="rage" and a.resource<cost: continue
  if t=="rage_all_min" and a.resource<int(s.get("min_cost") or 0): continue
  projected=min(100,a.resource+20) if "energy" in a.resource_type else a.resource
  if t in {"combat_energy","combat_energy_combo"} and projected<cost: continue
  if t=="combat_energy_combo" and a.combo<int(s.get("min_combo") or 1): continue
  return PvpActionIntent(a.user_id,"skill",s["key"])
 return PvpActionIntent(a.user_id,"basic_attack")

def simulate_duel(class_a,class_b,seed=1,max_rounds=50):
 if class_a not in CLASSES or class_b not in CLASSES: raise ValueError("unknown class")
 catalog=load_production_pvp_skill_catalog(); a=actor(1,class_a); b=actor(2,class_b)
 damage={1:0,2:0}; healing={1:0,2:0}; shields={1:0,2:0}; stuns={1:0,2:0}
 result=None
 for rnd in range(1,max_rounds+1):
  result=resolve_pvp_round(rnd,rnd,a,b,choose(a,catalog),choose(b,catalog),seed=seed*1000+rnd,catalog=catalog)
  for o in result.outcomes: damage[o.user_id]+=o.damage; healing[o.user_id]+=o.healing
  for e in result.events:
   if e.get("type")=="hot_tick": healing[int(e["user_id"])]+=int(e.get("value") or 0)
   if e.get("type")=="shield_absorb": shields[int(e["user_id"])]+=int(e.get("value") or 0)
  for o in result.outcomes:
   stuns[o.user_id]+=sum(1 for x in o.applied_effects if x.get("effect_key")=="stun_next")
  a=PvpActorState.from_dict(result.actor_a); b=PvpActorState.from_dict(result.actor_b)
  if result.terminal: break
 return {"class_a":class_a,"class_b":class_b,"winner":"a" if result.winner_id==1 else "b" if result.winner_id==2 else "draw","rounds":result.round_number,"hp_a":a.hp,"hp_b":b.hp,"damage_a":damage[1],"damage_b":damage[2],"healing_a":healing[1],"healing_b":healing[2],"shield_a":shields[1],"shield_b":shields[2],"stuns_a":stuns[1],"stuns_b":stuns[2],"reason":result.result_reason}

def _call(module, name: str, user_id: int, default: Any = 0) -> Any:
    function = getattr(module, name, None)
    if not callable(function):
        return default
    value = function(int(user_id))
    return default if value is None else value

def prepare_pvp_duel_snapshots(initiator_user_id: int, recipient_user_id: int, *, snapshot_provider: SnapshotProvider | None = None) -> dict[str, Any]:
    provider = snapshot_provider or build_production_pvp_snapshot
    try:
        return {
            "success": True,
            "initiator_snapshot": dict(provider(int(initiator_user_id))),
            "recipient_snapshot": dict(provider(int(recipient_user_id))),
        }
    except Exception as exc:
        LOGGER.exception("PvP snapshot preparation failed")
        return {"success": False, "reason": "pvp_snapshot_failed", "error": f"{type(exc).__name__}: {exc}"}

def create_pvp_battle_from_accepted_duel(request: Mapping[str, Any], *, snapshot_provider: SnapshotProvider | None = None, prepared_snapshots: Mapping[str, Any] | None = None, connection=None, activity_db_path=None) -> dict[str, Any]:
    if request.get("request_type") != "duel" or request.get("status") != "accepted":
        return {"success": False, "reason": "duel_request_not_accepted"}
    initiator = int(request["initiator_user_id"]); recipient = int(request["recipient_user_id"])
    prepared = dict(prepared_snapshots or prepare_pvp_duel_snapshots(initiator, recipient, snapshot_provider=snapshot_provider))
    if not prepared.get("success"):
        return prepared
    try:
        init_pvp_foundation(connection)
        created = create_pvp_battle(
            initiator, recipient, prepared["initiator_snapshot"], prepared["recipient_snapshot"],
            request_id=int(request["id"]), start_immediately=True, connection=connection,
        )
    except Exception as exc:
        LOGGER.exception("Persistent PvP battle creation failed for request %s", request.get("id"))
        return {"success": False, "reason": "pvp_battle_creation_failed", "error": f"{type(exc).__name__}: {exc}"}
    battle_id = int(created["battle"]["id"]); acquired = []
    for user_id in (initiator, recipient):
        result = acquire_player_activity_session(user_id, "pvp_battle", reference_id=battle_id, status="active", ttl_seconds=None, db_path=activity_db_path)
        if not result.get("success"):
            for previous in acquired:
                release_player_activity_session(previous, activity_type="pvp_battle", reference_id=battle_id, db_path=activity_db_path)
            complete_pvp_battle(battle_id, "activity_session_acquire_failed", status="cancelled", connection=connection)
            return {"success": False, "reason": "player_busy", "battle_id": battle_id}
        acquired.append(user_id)
    return {"success": True, "battle_id": battle_id, "battle": created["battle"], "participants": created["participants"]}

def _actor_display_name(actor: Mapping[str, Any], user_id: int) -> str:
    name = str(actor.get("character_name") or "").strip()
    if not name:
        try:
            from db import get_character_name
            name = str(get_character_name(int(user_id)) or "").strip()
        except Exception:
            name = ""
    return name or f"Гравець #{int(user_id)}"

def render_pvp_round_combat_log(payload: Mapping[str, Any], viewer_user_id: int) -> str:
    """Render a compact PvP round log with resource events grouped by owner."""
    round_number = int(payload.get("round_number") or 0)
    actors = {
        int(item.get("user_id")): item
        for item in payload.get("actors", ())
        if isinstance(item, Mapping) and item.get("user_id") is not None
    }
    events = [item for item in payload.get("events", ()) if isinstance(item, Mapping)]
    lines = [f"⚔️ <b>Раунд {round_number}</b>"]

    action_rage: dict[int, list[Mapping[str, Any]]] = {}
    damage_rage: list[Mapping[str, Any]] = []
    for event in events:
        kind = str(event.get("type") or "")
        uid = int(event.get("user_id") or 0)
        if kind in {"rage_gain_attack", "rage_gain_skill"}:
            action_rage.setdefault(uid, []).append(event)
        elif kind == "rage_gain_damage_taken":
            damage_rage.append(event)

    # Start-of-round events are displayed before combat actions.
    for event in events:
        kind = str(event.get("type") or "")
        if kind not in {"dot_tick", "hot_tick", "combat_energy_regen", "effect_expired"}:
            continue
        uid = int(event.get("user_id") or 0)
        who = escape(_actor_display_name(actors.get(uid, {}), uid))
        value = int(event.get("value") or 0)
        effect_label = escape(_effect_label(str(event.get("effect") or "effect")))
        effect_text = effect_label.replace("🛡️ ", "").replace("🩸 ", "").replace("☠️ ", "")
        if kind == "dot_tick":
            lines.append(f"{effect_label}: <b>{who}</b> отримує <b>{value}</b> шкоди.")
        elif kind == "hot_tick":
            lines.append(f"🌿 <b>{who}</b>: відновлено <b>{value}</b> HP.")
        elif kind == "combat_energy_regen":
            before = int(event.get("before") or 0)
            after = int(event.get("after") or 0)
            maximum = int(event.get("maximum") or 100)
            lines.append(f"⚡ <b>{who}</b>: +{value} Енергії → {after}/{maximum}")
        elif kind == "effect_expired":
            lines.append(f"⌛ <b>{who}</b>: {effect_text.lower()} завершилося")

    for outcome in payload.get("outcomes", ()):
        if not isinstance(outcome, Mapping):
            continue
        uid = int(outcome.get("user_id") or 0)
        actor = actors.get(uid, {})
        who = escape(_actor_display_name(actor, uid))
        action_type = str(outcome.get("action_type") or "")
        lines.append("")

        if action_type == "afk_skip":
            lines.append(f"⏳ <b>{who}</b> пропускає хід через бездіяльність")
            continue
        if action_type == "stunned_skip":
            lines.append(f"⚡ <b>{who}</b> оглушений і пропускає хід")
            continue
        if not bool(outcome.get("valid")):
            lines.append(f"⚠️ <b>{who}</b>: дію не виконано")
            continue

        skill_name = escape(_skill_name(str(actor.get("class_key") or ""), outcome.get("skill_key")))
        lines.append(f"<b>{who}</b> використав: {skill_name}.")
        if bool(outcome.get("dodged")):
            lines.append("💨 Суперник ухилився від атаки")
        elif int(outcome.get("damage") or 0) > 0:
            critical = " 💥 Критичний удар." if bool(outcome.get("critical")) else ""
            lines.append(f"🗡 Завдано <b>{int(outcome.get('damage') or 0)}</b> шкоди.{critical}")
        if int(outcome.get("healing") or 0) > 0:
            lines.append(f"❤️ Відновлено <b>{int(outcome.get('healing') or 0)}</b> HP.")

        icon, label = _resource_meta(actor)
        spent = int(outcome.get("resource_spent") or 0)
        gained = int(outcome.get("resource_gained") or 0)
        if spent > 0:
            lines.append(f"{icon} {label}: −{spent}")

        owner_rage = action_rage.get(uid, ())
        if owner_rage:
            total = sum(int(event.get("value") or 0) for event in owner_rage)
            after = int(owner_rage[-1].get("after") or actor.get("resource") or 0)
            lines.append(f"🔥 Лють: +{total} → {after}/100")
        elif gained > 0:
            lines.append(f"{icon} {label}: +{gained}")

        if int(outcome.get("combo_spent") or 0) > 0:
            lines.append(f"🔗 Комбо: −{int(outcome.get('combo_spent') or 0)} → 0/3")
        if int(outcome.get("combo_gained") or 0) > 0:
            lines.append(f"🔗 Комбо: +{int(outcome.get('combo_gained') or 0)} → {int(actor.get('combo') or 0)}/3")

        for effect in outcome.get("applied_effects", ()):
            if not isinstance(effect, Mapping):
                continue
            key = str(effect.get("effect_key") or effect.get("kind") or "effect")
            duration = int(effect.get("duration") or 0)
            power = int(round(float(effect.get("power") or 0)))
            suffix = f", {duration} {_round_word(duration)}" if duration > 0 else ""
            if key == "hot":
                lines.append(f"🌿 Відновлення здоров’я{suffix}")
            elif key == "shield":
                lines.append(f"🛡️ Накладено щит на {duration} {_round_word(duration)}." if duration else "🛡️ Накладено щит.")
            elif key == "mana_restore":
                lines.append(f"🔷 Мана: +{power}")
            elif key == "stun_next":
                lines.append("⚡ Оглушення на наступний раунд")
            elif key == "bleed":
                lines.append(f"🩸 Кровотеча{suffix}")
            elif key == "poison":
                lines.append(f"☠️ Отруєння{suffix}")
            else:
                lines.append(f"{escape(_effect_label(key))}{suffix}")

    # Incoming-damage Rage belongs to the damaged character, so the owner name is mandatory.
    for event in damage_rage:
        uid = int(event.get("user_id") or 0)
        who = escape(_actor_display_name(actors.get(uid, {}), uid))
        value = int(event.get("value") or 0)
        after = int(event.get("after") or actors.get(uid, {}).get("resource") or 0)
        lines.append(f"🔥 <b>{who}</b>: +{value} Люті від отриманої шкоди → {after}/100")

    for event in events:
        if str(event.get("type") or "") != "shield_absorb":
            continue
        uid = int(event.get("user_id") or 0)
        who = escape(_actor_display_name(actors.get(uid, {}), uid))
        value = int(event.get("value") or 0)
        lines.append(f"🛡️ <b>{who}</b>: щит поглинув <b>{value}</b> шкоди.")

    lines.append("")
    lines.extend(_state_lines(actors))
    return "\n".join(lines)

