        SIMPLE_RUNE_EXTRACTOR_GOLD_PRICE,
        SIMPLE_RUNE_EXTRACTOR_SHOP_ENABLED,
    )
    db = _db()
    conn = db.conn
    try:
        user_id = int(user_id)
        quantity = int(quantity)
    except Exception:
        return {
            "success": False,
            "code": "invalid_quantity",
