            }
        current_gold = round(float(row[0] or 0), 2)
        if current_gold + 1e-9 < total_price:
            conn.rollback()
            return {
                "success": False,
                "code": "not_enough_gold",
                "gold": current_gold,
                "required": total_price,
                "message": (
                    "❌ Недостатньо золота.\n\n"
                    f"Потрібно: {total_price:g} золота\n"
                    f"Доступно: {current_gold:g} золота"
