def is_expired_callback_query_error(method_name, error):
    """Return true only for Telegram's harmless expired callback acknowledgement."""
    if str(method_name) != "answer_callback_query":
        return False
    text = str(error or "").lower()
    if "error code: 400" not in text:
        return False
    return (
        "query is too old" in text
        or "response timeout expired" in text
        or "query id is invalid" in text
    )

def _guard_method(bot, method_name):
    original = getattr(bot, method_name, None)
    if not callable(original):
        return False
    if getattr(original, "_rom_global_429_guard_11_9_1", False):
        return False

    @wraps(original)
    def guarded(*args, **kwargs):
        chat_id = _extract_chat_id(method_name, args, kwargs)
        remaining = _remaining_seconds(chat_id)
        if remaining > 0:
            _record_suppressed(method_name, chat_id, remaining)
            return None
        try:
            return original(*args, **kwargs)
        except Exception as error:
            if is_expired_callback_query_error(method_name, error):
                PRODUCTION_LOG_PRINT(
                    PRODUCTION_LOGGER,
                    'warning',
                    f"⚠️ Expired Telegram callback acknowledgement contained: method={method_name}, chat={chat_id}. "
                    "Gameplay mutation was not replayed and polling may continue.",
                )
                return None
            retry_after = extract_retry_after(error)
            if retry_after is None:
                raise
            _register_flood_wait(chat_id, retry_after)
            PRODUCTION_LOG_PRINT(PRODUCTION_LOGGER, 'warning', f"⚠️ Telegram 429 contained globally: method={method_name}, "
                f"chat={chat_id}, retry_after={retry_after}s. "
                "Presentation was not retried; gameplay mutation will not be replayed.")
            return None

    guarded._rom_global_429_guard_11_9_1 = True
    guarded._rom_original_method_11_9_1 = original
    setattr(bot, method_name, guarded)
    return True

